solution:
// Create an array of numbers
const numbers = [1, 2, 3, 4, 5];

// Calculate the sum using a for loop
let sum = 0;
for (let i = 0; i < numbers.length; i++) {
  sum += numbers[i];
}

console.log('Sum:', sum); // Should output: Sum: 15
